<p class="lead-copy">Your next chapter, a little more organized.</p><div class="stats-grid"><?php foreach (['Saved places'=>'SELECT COUNT(*) FROM favorites WHERE user_id=?','Unlocked places'=>'SELECT COUNT(*) FROM unlocked_listings WHERE user_id=?','Simulated transactions'=>'SELECT COUNT(*) FROM unlock_transactions WHERE user_id=?'] as $label=>$sql): ?><div class="stat-card"><span><?= $label ?></span><strong><?= scalar($sql,[$user['id']]) ?></strong></div><?php endforeach; ?></div><h2>Recently explored</h2><?php $recent=rows(listing_select() . ' JOIN recent_views rv ON rv.dormitory_id=d.id WHERE rv.user_id=? AND ' . public_condition() . ' ORDER BY rv.viewed_at DESC LIMIT 3',[$user['id']]); ?><?php if ($recent): ?><div class="cards-grid dashboard-cards"><?php listing_cards($recent); ?></div><?php else: ?><div class="panel"><p>Your recently viewed places will appear here.</p><a class="btn btn-primary" href="<?= url('browse.php') ?>">Find your first favorite</a></div><?php endif; ?><h2 class="mt-5">Simulated transaction history</h2><?php $total=(int)scalar('SELECT COUNT(*) FROM unlock_transactions WHERE user_id=?',[$user['id']]); $transactions=rows('SELECT t.*,d.name dormitory FROM unlock_transactions t JOIN dormitories d ON d.id=t.dormitory_id WHERE t.user_id=? ORDER BY t.id DESC LIMIT 10 OFFSET ' . ((page_number()-1)*10),[$user['id']]); require ROOT . '/includes/transaction-table.php'; paginate($total,10); require ROOT . '/includes/dashboard-end.php'; ?>
